'use strict';
// These scripts run only in the trusted chat origin, never in the launcher renderer.
const READ="({token:localStorage.getItem('p5_signed_out')==='1'?'':(localStorage.getItem('p5_session')||sessionStorage.getItem('p5_session')||''),signedOut:localStorage.getItem('p5_signed_out')==='1'})";
function apply(token,uid=''){return `(async()=>{const wanted=${JSON.stringify(token)};const previous=typeof API_SESSION==='string'?API_SESSION:(localStorage.getItem('p5_session')||'');const expectedUID=${JSON.stringify(uid)};localStorage.setItem('p5_session',wanted);localStorage.removeItem('p5_signed_out');sessionStorage.removeItem('p5_session');if(typeof saveApiSession==='function')saveApiSession(wanted);if(expectedUID&&typeof CURRENT_USER!=='undefined'&&CURRENT_USER){if(CURRENT_USER.uid!==expectedUID)location.reload();return true;}if(previous!==wanted&&typeof restoreSession==='function'){for(let i=0;i<100&&typeof sessionRestorePending!=='undefined'&&sessionRestorePending;i++)await new Promise(resolve=>setTimeout(resolve,50));await restoreSession();}return true;})()`;}
const CLEAR="(()=>{if(typeof clearApiSession==='function')clearApiSession();localStorage.removeItem('p5_session');sessionStorage.removeItem('p5_session');localStorage.setItem('p5_signed_out','1');localStorage.removeItem('nn_session');localStorage.removeItem('nn_is_admin');location.reload();return true;})()";
function expiry(token,now=Date.now()){try{const p=JSON.parse(Buffer.from(token.split('.')[0],'base64url').toString());if(Number.isFinite(p.exp)&&p.exp>now)return Math.min(p.exp,now+30*86400000);}catch{}return now+86400000;}
module.exports={READ,apply,CLEAR,expiry};
